-- =====================================================================
--  54_bank_tarix_umumi.sql : UMUMI TARIX BANKI (9 ve 11-ci sinif)
--
--  BU FAYL ELLE YAZILMIR - tools/tarix_umumi.py yaradir:
--      python3 tools/tarix_umumi.py
--
--  12 movzu x 31 sual = 372.  Her movzuda 4 asan + 15 orta + 12 cetin.
--  ext_key: utarix9-/utarix11-...
--  ON SERT: 53_movzular_umumi_tarix.sql islenmis olmalidir.
--  SONRA:   05_grants.sql yeniden islet.
-- =====================================================================

do $$
begin
  if not exists (select 1 from public.topics t join public.subjects s
      on s.id = t.subject_id
     where s.slug = 'umumi-tarix' and t.slug in
           ('utarix-9-senaye', 'utarix-11-muasir')
     having count(*) = 2) then
    raise exception 'ONCE 53_movzular_umumi_tarix.sql isledilmelidir.';
  end if;
end $$;

delete from public.question_options o
 using public.questions q
 where o.question_id = q.id
   and q.owner_type = 'platform'
   and (q.ext_key like 'utarix9-%' or q.ext_key like 'utarix11-%');

