('utarix11-muasir#29','umumi-tarix','utarix-11-muasir',3,4,'2008-ci il qlobal maliyyə böhranı nəyi göstərdi?','Maliyyə bazarlarının bağlılığı səbəbindən böhran sürətlə qitələrə yayıla bilir.',array['Böhranın sürətlə qlobal yayılmasını','Ölkələrin tam iqtisadi müstəqilliyini','Qlobal ticarətin faydasız olduğunu','İnternetin iqtisadiyyata zərərini'],1),
('utarix11-muasir#30','umumi-tarix','utarix-11-muasir',3,4,'Müasir dünyada Azərbaycanın mövqeyini gücləndirən əsas amil hansıdır?','Enerji resursları və Şərq-Qərb, Şimal-Cənub dəhlizlərinin kəsişməsindəki coğrafi mövqe.',array['Enerji resursları və nəqliyyat dəhlizləri','Okean sahilində yerləşməsi','Qütb bölgəsindəki əraziləri','Ada dövləti olması və donanması'],1),
('utarix11-muasir#31','umumi-tarix','utarix-11-muasir',3,4,'Beynəlxalq təşkilatların qlobal problemləri həll etməkdə əsas çətinliyi nədir?','Dövlətlərin milli maraqları ilə qlobal maraqların uzlaşdırılmasıdır.',array['Milli və qlobal maraqların uzlaşdırılması','Elmi biliklərin kifayət qədər olmaması','Texnoloji imkanların çatışmazlığı','Qlobal səviyyədə dil fərqlərinin olması'],1)
),
ins as (
  insert into public.questions
    (ext_key, owner_type, subject_id, level_id, topic_id, kind,
     body, explanation, difficulty, quarter, status)
  select d.ext, 'platform', s.id, tp.level_id, tp.id, 'single',
         d.body, d.why, d.diff, d.rub, 'published'
    from d
    join public.subjects s on s.slug = d.fenn
    join public.topics   tp on tp.subject_id = s.id and tp.slug = d.topic
  on conflict (ext_key) do update
    set body = excluded.body, explanation = excluded.explanation,
        difficulty = excluded.difficulty, quarter = excluded.quarter,
        topic_id = excluded.topic_id, level_id = excluded.level_id,
        subject_id = excluded.subject_id, status = 'published'
  returning id, ext_key
)
insert into public.question_options (question_id, ord, body, is_correct)
select ins.id, o.ord, o.txt, o.ord = d.correct
  from ins
  join d on d.ext = ins.ext_key,
  lateral unnest(d.opts) with ordinality as o(txt, ord);

do $$
declare n int; k int;
begin
  select count(*) into n from public.questions
   where owner_type = 'platform'
     and (ext_key like 'utarix9-%' or ext_key like 'utarix11-%');
  if n <> 372 then
    raise exception 'Umumi tarix suallari: 372 gozlenilirdi, % tapildi', n;
  end if;
  select count(*) into k from public.questions q
   where (q.ext_key like 'utarix9-%' or q.ext_key like 'utarix11-%')
     and ((select count(*) from public.question_options o
            where o.question_id = q.id) <> 4
       or (select count(*) from public.question_options o
            where o.question_id = q.id and o.is_correct) <> 1);
  if k > 0 then
    raise exception '% sualda variant qurulusu sehvdir', k;
  end if;
  select count(distinct topic_id) into k from public.questions
   where ext_key like 'utarix9-%' or ext_key like 'utarix11-%';
  if k <> 12 then
    raise exception 'movzu sayi 12 deyil: %', k;
  end if;
  --  Her movzuda en azi 12 cetin sual olmalidir ki, muellim BIR
  --  movzudan 10 sualliq cetin test yiga bilsin
  select count(*) into k from (
    select q.topic_id from public.questions q
     where (q.ext_key like 'utarix9-%' or q.ext_key like 'utarix11-%')
       and q.difficulty = 3
     group by q.topic_id having count(*) < 12) z;
  if k > 0 then
    raise exception '% movzuda 12-den az cetin sual var', k;
  end if;
  raise notice 'Umumi tarix banki: % sual, 12 movzu (her birinde 12 cetin).', n;
end $$;
